// Interactive demo: background Gaussians (.splat) + placed object meshes (.glb) of scenes
// generated by Pano3DComposer. The world frame of the outputs is z-up; three.js is y-up.
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import * as GaussianSplats3D from "@mkkellogg/gaussian-splats-3d";

const SCENES = {
  lythwood_room: { title: "Lythwood Room", yaw: Math.PI },
  photo_studio_loft_hall: { title: "Photo Studio Loft Hall", yaw: 0 },
  poly_haven_studio: { title: "Poly Haven Studio", yaw: 1.5 * Math.PI },
};
const Z_UP_TO_Y_UP = [-Math.SQRT1_2, 0, 0, Math.SQRT1_2]; // rotation of -90 deg about x (x, y, z, w)

const root = document.getElementById("demo-viewer");
const status = document.getElementById("demo-status");
const bgToggle = document.getElementById("demo-bg");
const objToggle = document.getElementById("demo-obj");

const renderer = new THREE.WebGLRenderer({ antialias: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
root.prepend(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x111214);

const camera = new THREE.PerspectiveCamera(70, 1, 0.01, 100);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.minDistance = 0.05;
controls.maxDistance = 3.0;

let current = null; // { name, splat, objects }
let loadToken = 0;

function resize() {
  const w = root.clientWidth, h = root.clientHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(root);

function resetView(yaw) {
  // Start just behind the panorama center (the capture position), looking into the room.
  const dir = new THREE.Vector3(Math.sin(yaw), 0, -Math.cos(yaw));
  controls.target.copy(dir.clone().multiplyScalar(0.6)).setY(-0.25);
  camera.position.copy(dir.clone().multiplyScalar(-0.6)).setY(0.15);
  controls.update();
}

async function load(name) {
  const token = ++loadToken;
  status.hidden = false;
  status.textContent = `Loading ${SCENES[name].title}…`;
  if (current) {
    scene.remove(current.splat, current.objects);
    current.splat.dispose();
    current = null;
  }
  const base = `./static/demo/${name}/`;
  const splat = new GaussianSplats3D.DropInViewer({ sharedMemoryForWorkers: false, gpuAcceleratedSort: false });
  const objects = new THREE.Group();
  const gltf = new GLTFLoader().loadAsync(base + "objects.glb");
  await splat.addSplatScene(base + "background.splat", {
    rotation: Z_UP_TO_Y_UP,
    showLoadingUI: false,
    splatAlphaRemovalThreshold: 5,
    format: GaussianSplats3D.SceneFormat.Splat,
  });
  const meshes = (await gltf).scene;
  // The generated textures already contain shading, so show them unlit (as in the Gaussian renders).
  meshes.traverse(o => {
    if (o.isMesh) o.material = new THREE.MeshBasicMaterial({ map: o.material.map, color: o.material.color, side: THREE.DoubleSide });
  });
  objects.add(meshes);
  if (token !== loadToken) { splat.dispose(); return; }
  splat.visible = bgToggle.checked;
  objects.visible = objToggle.checked;
  scene.add(splat, objects);
  current = { name, splat, objects };
  resetView(SCENES[name].yaw);
  status.hidden = true;
}

bgToggle.addEventListener("change", () => current && (current.splat.visible = bgToggle.checked));
objToggle.addEventListener("change", () => current && (current.objects.visible = objToggle.checked));
document.getElementById("demo-reset").addEventListener("click", () => current && resetView(SCENES[current.name].yaw));

// scene buttons, and the panorama / render comparison below the viewer
const compare = document.getElementById("demo-compare");
function select(name) {
  document.querySelectorAll("#demo-scenes button").forEach(b => {
    const on = b.dataset.scene === name;
    b.classList.toggle("is-dark", on);
    b.setAttribute("aria-pressed", on);
  });
  compare.querySelector(".demo-pano").src = `./static/demo/${name}/panorama.jpg`;
  compare.querySelector(".demo-render").src = `./static/demo/${name}/render.jpg`;
  load(name).catch(e => { status.hidden = false; status.textContent = `Could not load the scene (${e.message}).`; });
}
document.querySelectorAll("#demo-scenes button").forEach(b => b.addEventListener("click", () => select(b.dataset.scene)));
document.getElementById("demo-cut").addEventListener("input", e => compare.style.setProperty("--cut", `${e.target.value}%`));

renderer.setAnimationLoop(() => {
  controls.update();
  renderer.render(scene, camera);
});
resize();

// Start loading (about 25 MB per scene) only when the demo scrolls into view.
const io = new IntersectionObserver(entries => {
  if (entries.some(e => e.isIntersecting)) {
    io.disconnect();
    select("lythwood_room");
  }
}, { rootMargin: "200px" });
io.observe(root);
